/**
 * Insert 100 user-focused KB articles (USR-101 to USR-200) into the database
 * Run: node scripts/insert-user-kb-articles.mjs
 */
import { createConnection } from 'mysql2/promise';
import { readFileSync } from 'fs';
import { config } from 'dotenv';

config({ path: '/home/ubuntu/gigitekai/.env' });

const DB_URL = process.env.DATABASE_URL;
if (!DB_URL) { console.error('DATABASE_URL not found'); process.exit(1); }

// Parse mysql://user:pass@host:port/dbname?params
const match = DB_URL.match(/mysql:\/\/([^:]+):([^@]+)@([^:\/]+):(\d+)\/([^?]+)/);
if (!match) { console.error('Could not parse DATABASE_URL'); process.exit(1); }
const [, user, password, host, port, database] = match;

const conn = await createConnection({ host, port: parseInt(port), user, password, database, ssl: { rejectUnauthorized: false } });
console.log('Connected to database');

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');

// Helper: build markdown content from structured data
function buildContent(code, title, category, symptoms, rootCause, steps) {
  return `## ${title}\n\n**Article ID:** ${code}\n\n**Symptoms:** ${symptoms}\n\n**Root Cause:** ${rootCause}\n\n### Resolution Steps\n\n${steps.map((s, i) => `${i+1}. ${s}`).join('\n')}\n\n**Category:** ${category}`;
}

const articles = [
  // ─── Wireless & Internet (USR-101 to USR-104) ───
  { code:'USR-101', title:'Wi-Fi Keeps Disconnecting Every Few Minutes at Your Desk', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'wifi,wireless,disconnecting,network,connectivity,business-user,office-teams', symptoms:'Laptop Wi-Fi drops every few minutes, cutting off Teams calls and email sync.', cause:'Windows power management is turning off the wireless adapter to save battery.', steps:['Right-click Start Menu and select Device Manager.','Expand Network adapters and double-click your Wi-Fi adapter.','Click the Power Management tab.','Uncheck Allow the computer to turn off this device to save power. Click OK.','Open Control Panel > Network and Sharing Center > Change adapter settings.','Right-click your Wi-Fi and select Properties > Configure > Advanced.','Find Roaming Aggressiveness and set it to Lowest. Click OK.'] },
  { code:'USR-102', title:'Corporate Wi-Fi Network Not Showing Up in Available Networks List', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'wifi,wireless,network,ssid,missing,connectivity,business-user', symptoms:'Company network SSID not listed among available networks.', cause:'Wireless adapter is disabled or the 5GHz band is not broadcasting in your area.', steps:['Press Win+X and select Device Manager.','Expand Network adapters, right-click your Wi-Fi adapter, and select Enable device if disabled.','Toggle Wi-Fi Off in taskbar, wait 5 seconds, toggle back On.','Go to Settings > Network & Internet > Wi-Fi > Manage known networks, remove old entries.','Move closer to the access point if still missing.'] },
  { code:'USR-103', title:'Internet Speed is Extremely Slow on Corporate Laptop Only', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'internet,slow,speed,network,connectivity,business-user,performance', symptoms:'Websites load slowly and Teams calls buffer, but other devices work fine.', cause:'A background Windows Update or antivirus scan is consuming bandwidth.', steps:['Press Ctrl+Shift+Esc to open Task Manager.','Click the Network column header to sort by highest usage.','Identify the process consuming bandwidth (Windows Update, antivirus, OneDrive sync).','Right-click that process and select End Task to pause it temporarily.','For Windows Update: go to Settings > Windows Update > Pause updates for 1 week.'] },
  { code:'USR-104', title:'VPN Connected but Internet Browsing Stopped Working Completely', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'vpn,internet,browsing,connectivity,network,business-user,remote-work', symptoms:'VPN shows Connected but no websites load and Teams cannot connect.', cause:'VPN is routing all traffic through the corporate tunnel, which has a DNS resolution issue.', steps:['Open your VPN client and click Disconnect.','Open a browser and verify internet works without VPN.','Reconnect the VPN. If browsing fails again, open the VPN settings.','Look for a Split Tunneling option and enable it to allow local internet traffic.','If no split tunneling option, contact IT to report the DNS issue.'] },
  // ─── Monitors & Displays (USR-105 to USR-108) ───
  { code:'USR-105', title:'Second Monitor Not Detected After Connecting HDMI Cable', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,hdmi,display,second-screen,hardware,business-user', symptoms:'External monitor stays black after plugging in HDMI cable.', cause:'Windows did not auto-detect the new display. A manual detection trigger is needed.', steps:['Right-click an empty area on your desktop and select Display settings.','Scroll down and click the Detect button under the Multiple displays section.','If detected, select Extend these displays from the dropdown.','If not detected, try pressing Win+P and select Extend.','Try a different HDMI port on your laptop or dock if still not working.'] },
  { code:'USR-106', title:'Monitor Screen Flickering or Flashing Randomly', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,flickering,display,screen,hardware,business-user', symptoms:'Screen flickers or flashes randomly while working.', cause:'Incompatible display driver or a loose video cable connection.', steps:['Check that the HDMI or DisplayPort cable is firmly seated at both ends.','Right-click the desktop and select Display settings > Advanced display settings.','Check the Refresh rate — change it to 60 Hz if set higher.','Open Device Manager, expand Display adapters, right-click your GPU, and select Update driver.','If flickering persists, try a different cable.'] },
  { code:'USR-107', title:'Display Resolution Looks Blurry or Too Large After Windows Update', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,resolution,display,blurry,windows,business-user', symptoms:'Screen looks blurry or icons appear oversized after a Windows update.', cause:'Windows Update reset the display scaling settings to a non-native resolution.', steps:['Right-click the desktop and select Display settings.','Under Display resolution, select the Recommended option (usually the highest available).','Under Scale, set it to 100% or 125% depending on your screen size.','Click Apply and confirm the change.','If text still looks blurry in specific apps, right-click the app shortcut > Properties > Compatibility > Change high DPI settings > Override high DPI scaling behavior.'] },
  { code:'USR-108', title:'Screen Goes Black for 2 Seconds Randomly While Working', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,black-screen,display,flickering,hardware,business-user', symptoms:'Screen briefly goes completely black for 1-2 seconds then returns to normal.', cause:'Windows is switching display modes or the graphics driver is resetting.', steps:['Right-click the desktop > Display settings > Advanced display settings.','Ensure the refresh rate matches your monitor spec (60 Hz standard).','Open Device Manager > Display adapters > right-click GPU > Update driver.','If using a docking station, ensure the dock firmware is up to date.','Check the video cable for damage and try replacing it.'] },
  // ─── Audio & Video Conferencing (USR-109 to USR-112) ───
  { code:'USR-109', title:'No Sound Coming from Laptop Speakers or Headset', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'audio,sound,speakers,headset,hardware,business-user,office-teams', symptoms:'No audio output from speakers or headset during calls or media playback.', cause:'Windows selected the wrong audio output device after a recent connection change.', steps:['Right-click the speaker icon in the taskbar and select Open Sound settings.','Under Output, click the dropdown and select your correct speaker or headset.','Ensure the volume slider is not at zero.','Click Troubleshoot to run the Windows audio troubleshooter.','If using a USB headset, unplug and replug it to force Windows to re-detect it.'] },
  { code:'USR-110', title:'Microphone Not Working in Microsoft Teams or Zoom', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'microphone,audio,teams,zoom,video-call,business-user,office-teams', symptoms:'Others cannot hear you during video calls even though your mic appears selected.', cause:'The app does not have microphone permission, or the wrong input device is selected.', steps:['In Teams: click your profile picture > Settings > Devices. Ensure the correct microphone is selected.','In Windows: go to Settings > Privacy > Microphone and ensure Allow apps to access your microphone is On.','Ensure Microsoft Teams is listed and enabled in the app permissions list.','Test the mic by clicking the Make a test call button in Teams Device settings.','If using a headset, check that it is fully plugged in and not muted via the physical mute button.'] },
  { code:'USR-111', title:'Camera Not Showing Video in Teams or Zoom Meeting', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'camera,video,webcam,teams,zoom,business-user,office-teams', symptoms:'Camera appears selected but video feed is black or not showing.', cause:'Another application is using the camera, or camera permissions are blocked.', steps:['Close all other apps that might use the camera (Skype, FaceTime, other video apps).','Go to Settings > Privacy > Camera and ensure Allow apps to access your camera is On.','In Teams: Settings > Devices > Camera — select your webcam from the dropdown.','If camera shows as disabled in Device Manager, right-click and select Enable device.','Try unplugging and replugging a USB webcam to force re-detection.'] },
  { code:'USR-112', title:'Echo or Feedback Noise During Video Calls', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'echo,feedback,audio,video-call,teams,zoom,business-user,office-teams', symptoms:'Loud echo or whistling noise during calls that disrupts the meeting.', cause:'Laptop speakers are picking up audio and re-amplifying it through the microphone.', steps:['Immediately mute your microphone to stop the feedback loop.','Lower your speaker volume below 50%.','Use headphones or earbuds to isolate audio directly to your ears.','If in a conference room with multiple people, ensure only one device has mic and speakers active.','Enable noise suppression in Teams: Settings > Devices > Noise suppression > High.'] },
  // ─── Web Browsers (USR-113 to USR-118) ───
  { code:'USR-113', title:'Browser Keeps Crashing on Corporate Web Apps', cat:'Software & Applications', sub:'Web Browsers', tags:'browser,crash,chrome,edge,web-app,business-user', symptoms:'Browser tab crashes with Aw Snap error when using corporate web tools.', cause:'Memory leak in the web app or conflicting browser extensions.', steps:['Press Ctrl+Shift+R to hard refresh the page.','Click the extension puzzle icon and disable third-party extensions.','Open browser Settings > System > enable Memory Saver mode.','Clear browser cache: Ctrl+Shift+Delete > Cached images and files > Clear data.','Try opening the app in a new InPrivate/Incognito window to test without extensions.'] },
  { code:'USR-114', title:'Browser Running Slowly with Many Open Tabs', cat:'Software & Applications', sub:'Web Browsers', tags:'browser,slow,performance,tabs,chrome,edge,business-user', symptoms:'Browser becomes sluggish and unresponsive with multiple tabs open.', cause:'Too many tabs consuming system memory and CPU resources.', steps:['Close tabs you are not actively using.','Press Shift+Esc inside Chrome or Edge to open the browser Task Manager.','Sort by Memory column and End Process on the heaviest tabs.','Remove unused extensions from the puzzle-piece icon menu.','Enable Memory Saver in browser Settings > Performance.'] },
  { code:'USR-115', title:'Mouse Cursor Lagging or Jumping Across the Screen', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'mouse,cursor,lag,hardware,peripherals,business-user', symptoms:'Mouse pointer stutters, moves erratically, or stops responding for seconds.', cause:'Optical sensor is obstructed by dust, or wireless signal is blocked.', steps:['Flip the mouse and clean the optical sensor lens with a microfiber cloth.','Move the USB wireless receiver to a front-facing port closer to the mouse.','Replace batteries if the mouse is wireless and batteries are old.','Try using the mouse on a different surface (avoid glass or reflective surfaces).','Update mouse drivers via Device Manager > Mice and other pointing devices.'] },
  { code:'USR-116', title:'Mapped Network Drive Shows Red X and Will Not Open', cat:'Network & Connectivity', sub:'Shared Files', tags:'network-drive,mapped-drive,vpn,file-sharing,business-user,remote-work', symptoms:'Network drive icon shows a red X and returns Network path not found error.', cause:'Working remotely without VPN active — no line of sight to the file server.', steps:['Locate your VPN client in the taskbar notification tray.','Open the VPN app and click Connect. Complete MFA if prompted.','Once Connected, close any open File Explorer windows.','Open a fresh File Explorer window and double-click the network drive.','The red X will clear and your shared files will load normally.'] },
  { code:'USR-117', title:'Keyboard Typing Lag — Letters Appear 2 Seconds Late', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'keyboard,typing,lag,filter-keys,accessibility,business-user', symptoms:'Typed letters appear on screen with a 1-2 second delay.', cause:'Windows Filter Keys accessibility setting was accidentally activated.', steps:['Open Start Menu, type Accessibility, and select Accessibility keyboard settings.','Scroll to Filter Keys and check the toggle — if On, turn it Off.','If Filter Keys was already off, open Task Manager (Ctrl+Shift+Esc).','Click the Processes tab and close any apps showing high CPU usage.','Restart the computer if lag persists after closing background apps.'] },
  { code:'USR-118', title:'Bluetooth Mouse and Keyboard Both Disconnected Simultaneously', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'bluetooth,mouse,keyboard,wireless,disconnect,business-user', symptoms:'Both Bluetooth mouse and keyboard disconnect at the same time.', cause:'Bluetooth driver crashed or Airplane Mode was accidentally activated.', steps:['Use the laptop trackpad and built-in keyboard temporarily.','Look for the Airplane Mode key (F-row) and press it to ensure Airplane Mode is Off.','Open Settings > Bluetooth & devices and toggle Bluetooth Off, wait 5 seconds, toggle On.','Remove and re-pair your Bluetooth devices from the Bluetooth settings.','If issue recurs, update Bluetooth drivers via Device Manager.'] },
  // ─── Core Corporate Software (USR-119 to USR-125) ───
  { code:'USR-119', title:'Copy and Paste (Ctrl+C / Ctrl+V) Stopped Working', cat:'Software & Applications', sub:'Core Software', tags:'copy-paste,clipboard,windows,software,business-user', symptoms:'Ctrl+C and Ctrl+V do nothing — clipboard appears completely empty.', cause:'A background utility locked the clipboard memory pipeline.', steps:['Open Start Menu, type Clipboard, and select Clipboard settings.','Click the Clear button under Clear clipboard data.','If still broken, open Task Manager (Ctrl+Shift+Esc).','Find Windows Explorer (explorer.exe) in Processes, right-click, and select Restart.','The taskbar will flash for a second — clipboard will reset and work normally.'] },
  { code:'USR-120', title:'Accidentally Sent a Large Print Job to the Wrong Printer', cat:'Software & Applications', sub:'Printing', tags:'printing,print-queue,cancel,printer,business-user', symptoms:'A large document was sent to the wrong printer and needs to be cancelled.', cause:'Document is in the local print spooler queue waiting to transmit.', steps:['Look for the Printer icon in the bottom-right taskbar tray.','Double-click it to open the active print queue window.','Locate your document in the list.','Right-click the document and select Cancel.','Click Yes to confirm — the document will show Deleting and vanish from the queue.'] },
  { code:'USR-121', title:'Corporate VPN Client Shows Gateway Connection Refused', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'vpn,gateway,connection-refused,remote-work,network,business-user', symptoms:'VPN returns Gateway Connection Refused or Server Not Responding error.', cause:'Local network path is blocked or the app has a stuck authentication token.', steps:['Open a browser and verify basic internet works (try google.com).','In the VPN app, delete and retype the gateway address exactly as provided by IT.','Right-click the VPN icon in the taskbar and choose Quit/Exit.','Reopen the VPN client from the Start Menu to load fresh authentication.','Contact IT if the issue persists after fresh authentication.'] },
  { code:'USR-122', title:'MFA App Notifications Not Appearing on Phone', cat:'Account & Authentication', sub:'Identity & Access', tags:'mfa,authenticator,notification,identity,access,business-user,entra-id', symptoms:'Corporate login says notification sent but phone stays silent.', cause:'Authenticator app is in deep sleep mode with background notifications restricted.', steps:['Unlock your phone and manually open the Microsoft Authenticator app.','The app will force a refresh and show the pending approval prompt.','If no prompt appears, copy the 6-digit code shown next to your work account.','Enter that code manually on the computer login screen.','To fix permanently: go to phone Settings > Apps > Authenticator > Battery > Allow background activity.'] },
  { code:'USR-123', title:'Docking Station Charges Laptop but External Monitors Stay Black', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'docking-station,monitor,display,hardware,business-user', symptoms:'Laptop charges via dock but external monitors and accessories remain dead.', cause:'Docking station microcontroller entered a locked state after a power surge.', steps:['Disconnect the USB-C dock cable from your laptop.','Unplug the power cable from the docking station.','Wait 15 seconds to let internal chips drain.','Plug the power cable back into the dock.','Reconnect the USB-C cable to your laptop — displays will initialize cleanly.'] },
  { code:'USR-124', title:'All Desktop Icons and Shortcuts Disappeared', cat:'Software & Applications', sub:'Windows Endpoint', tags:'desktop,icons,missing,windows,business-user', symptoms:'Desktop is completely blank — all icons and shortcuts have vanished.', cause:'Show desktop icons was accidentally toggled off.', steps:['Right-click an empty area on the desktop.','Hover over View in the context menu.','Look for Show desktop icons in the submenu.','Click Show desktop icons to add the checkmark.','All icons and shortcuts will instantly reappear.'] },
  { code:'USR-125', title:'Mac Spinning Rainbow Wheel Every Time an Office App Opens', cat:'Software & Applications', sub:'macOS Endpoint', tags:'mac,rainbow-wheel,office,word,excel,outlook,macos,business-user', symptoms:'Office apps freeze with spinning beachball cursor immediately on launch.', cause:'App preference state file or font cache entered a locked conflict loop.', steps:['Force quit the frozen app: Apple menu > Force Quit.','Open Finder > Go (hold Option key) > Library.','Navigate to Library > Containers.','Find and drag the problem app folder (e.g., com.microsoft.Word) to Trash.','Relaunch the app — it will build a clean preference file and boot normally.'] },
  // ─── Microsoft Copilot (USR-126 to USR-130) ───
  { code:'USR-126', title:'Microsoft Copilot Button Missing from Office Apps', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,microsoft-365,office,ribbon,ms-copilot,business-user', symptoms:'Copilot icon is completely missing from the Word, Excel, or PowerPoint ribbon.', cause:'Office has not refreshed its cloud licensing profile since the AI entitlement was added.', steps:['Open any Office app (e.g., Word) and click File > Account.','Click Update Options > Update Now to ensure Office is fully updated.','Click Sign Out next to your profile.','Close all Office apps completely.','Reopen Word, sign in with corporate credentials — Copilot icon will appear.'] },
  { code:'USR-127', title:'Copilot Shows Privacy or Sensitivity Label Error', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,sensitivity-label,purview,compliance,ms-copilot,business-user', symptoms:'Copilot returns This document has a sensitivity label that restricts Copilot access.', cause:'File has a highly restrictive Purview Sensitivity Label applied.', steps:['Look at the top of the document to see which sensitivity label is applied.','If authorized to change it, click the Sensitivity shield button on the Home tab.','Lower the label to General or Confidential - Internal.','Save the document, close it, and wait 30 seconds.','Reopen the file from OneDrive or SharePoint and try Copilot again.'] },
  { code:'USR-128', title:'Excel Copilot Button is Greyed Out and Unclickable', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,excel,table,autosave,ms-copilot,business-user,office-excel', symptoms:'Copilot icon in Excel is transparent or greyed out and clicking does nothing.', cause:'Copilot in Excel only works with cloud-saved files formatted as Excel Tables.', steps:['Ensure AutoSave is On in the upper-left corner (save to OneDrive first if needed).','Highlight your data range.','On the Home tab, click Format as Table and choose a style.','Ensure My table has headers is checked and click OK.','The Copilot button will light up and become fully functional.'] },
  { code:'USR-129', title:"Copilot Can't Find or Reference a Specific File", cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,file-reference,onedrive,sharepoint,ms-copilot,business-user', symptoms:'Copilot returns I cannot find that file when asked to analyze a document.', cause:'File is stored locally or was uploaded too recently for cloud indexers to map.', steps:['Verify the document is uploaded to OneDrive or SharePoint (not local C: drive).','Open the file in a browser, click Share, and copy the link.','Go to Copilot chat and type / or click the attachment icon.','Paste the URL directly into the prompt box next to your question.','Copilot will follow the link and read the file directly.'] },
  { code:'USR-130', title:'Outlook Copilot Draft Sounds Too Formal or Refuses to Draft', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,outlook,email-draft,tone,ms-copilot,business-user,office-outlook', symptoms:'Copilot draft sounds stiff or stops mid-sentence with a Content Boundaries error.', cause:'Prompt lacked stylistic guidance or triggered content filter keywords.', steps:['Delete the draft and click Draft with Copilot again.','Click the Adjust options icon (sliding dials) at the bottom of the prompt box.','Change Tone to Casual, Direct, or Creative and set Length to Short.','Write an explicit prompt: Draft a polite reminder to John about the 4 PM deadline. Keep it to three sentences.','Click Generate for an adjusted, natural-sounding response.'] },
  // ─── M365 Apps (USR-131 to USR-140) ───
  { code:'USR-131', title:'Word Document Shows Upload Blocked or Cache Conflict Error', cat:'Microsoft 365', sub:'M365 Apps', tags:'word,upload-blocked,cache,onedrive,sync,business-user,office-word', symptoms:'Red or yellow warning bar says Upload Blocked or Your cached copy is out of date.', cause:'Network dropout interrupted the real-time sync between Office and the cloud.', steps:['Do not close the document yet. Click File > Save a Copy to save a local backup.','Click Resolve or Keep My Version in the warning banner.','If error remains, click File > Info > Discard Changes to pull the clean server copy.','To clear the cache: click the OneDrive icon in taskbar > Settings > Advanced Settings > Delete Cached Files.','Reopen the document from OneDrive.'] },
  { code:'USR-132', title:'PowerPoint Designer Panel Refuses to Load Suggestions', cat:'Microsoft 365', sub:'M365 Apps', tags:'powerpoint,designer,design-ideas,slide,business-user,office-powerpoint', symptoms:'Designer panel stays blank or shows No suggestions found.', cause:'Slide uses an older legacy template or internet connection dropped.', steps:['Click File > Info and click Convert if visible (updates to modern format).','Go to Home tab > Layout and select a standard Title Slide or Title and Content layout.','Remove any oversized custom shapes or third-party graphics from the slide.','Ensure your internet connection is active.','Toggle the Designer panel off and back on to refresh suggestions.'] },
  { code:'USR-133', title:'Excel Formula Shows a #SPILL! Error', cat:'Microsoft 365', sub:'M365 Apps', tags:'excel,spill-error,formula,xlookup,dynamic-array,business-user,office-excel', symptoms:'Cell shows #SPILL! error instead of calculated results.', cause:'A dynamic array formula is blocked by existing content in the spill range.', steps:['Click the cell showing #SPILL!.','Look for the faint dashed blue border showing the intended spill range.','Scan those highlighted rows for any text, numbers, or spaces blocking the range.','Delete or move the blocking content to a different column.','The formula will immediately flow down the column cleanly.'] },
  { code:'USR-134', title:'OneNote Notebook Section Shows Red Exclamation Sync Error', cat:'Microsoft 365', sub:'M365 Apps', tags:'onenote,sync-error,notebook,sharepoint,business-user,office-teams', symptoms:'Red circle with exclamation mark next to notebook tab — notes fail to sync.', cause:'Local notebook cache credentials desynchronized from SharePoint after an access rule update.', steps:['Do not close or delete the unsynced notebook section.','Open OneNote Online in a browser (office.com > OneNote).','Open the same notebook in the browser.','In the desktop app, create a new section and copy unsynced notes there.','Right-click the notebook name > Sync > Sync This Notebook Now.'] },
  { code:'USR-135', title:'Shared Files Open in Browser Instead of Desktop App', cat:'Microsoft 365', sub:'M365 Apps', tags:'office,desktop-app,browser,teams,file-open,business-user', symptoms:'Clicking document links opens them in a browser tab instead of the desktop app.', cause:'Teams or OS default file association is set to browser.', steps:['In Teams: click ... next to profile > Settings > Files and links.','Change File open preference to Desktop app.','In Word/Excel: File > Options > Advanced > Link Handling.','Check Open Word, Excel, and PowerPoint files in Office desktop apps by default.','Click OK to save.'] },
  { code:'USR-136', title:'Teams Meeting Recording Missing After Call Ends', cat:'Microsoft 365', sub:'M365 Apps', tags:'teams,recording,transcript,onedrive,meeting,business-user,office-teams', symptoms:'Meeting recording does not appear in the chat thread after the call ends.', cause:'Recording takes time to process or was saved to personal OneDrive instead of channel.', steps:['Wait up to 15 minutes for the recording to process.','Open OneDrive in a browser.','Navigate to My Files > Recordings.','Find the MP4 file and transcript there.','Click ... > Share and copy the link to send to meeting participants.'] },
  { code:'USR-137', title:'Outlook Scheduling Assistant Shows Blank No Information Bars', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,scheduling-assistant,calendar,free-busy,business-user,office-outlook', symptoms:'Colleague calendar rows show grey hash marks and No Information instead of availability.', cause:'Outlook desktop client dropped its sync connection with the cloud directory server.', steps:['Open Outlook on the web (outlook.office.com) and use the Scheduling Assistant there.','The web app communicates directly with cloud databases and shows accurate availability.','To fix the desktop client: click the Send/Receive tab.','Click Download Address Book and ensure Download changes since last Send/Receive is checked.','Click OK to pull fresh sync records.'] },
  { code:'USR-138', title:'Copilot Studio Chatbot Returns Error Code: Talk to Admin', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot-studio,chatbot,authentication,sso,ms-copilot,business-user,microsoft-copilot-studio', symptoms:'Internal AI chatbot returns Error Code: 2001 / Talk to your Administrator.', cause:'Web authentication session token expired, blocking identity verification.', steps:['Close the browser tab or app housing the chatbot.','Sign out of your company dashboard single sign-on page.','Clear browser cache: Ctrl+Shift+Delete > Cookies and other site data > Clear Data.','Open a clean browser window and log back in to your corporate portal.','Reopen the chatbot — it will authenticate with fresh tokens.'] },
  { code:'USR-139', title:'M365 Web Apps Stuck in Endless Login Loop', cat:'Account & Authentication', sub:'Identity & Access', tags:'office,login-loop,cookies,authentication,browser,business-user,entra-id', symptoms:'Logging into office.com loops back to the login page repeatedly.', cause:'Browser is blocking third-party cookies required for Microsoft authentication.', steps:['Look for a crossed-out cookie or shield icon in the browser address bar.','Click it and select Allow cookies or Turn off tracking prevention for this site.','In Chrome: Settings > Privacy and security > Third-party cookies > change to Block in Incognito only.','Refresh the login page.','If still looping, try a different browser (Edge is recommended for M365).'] },
  { code:'USR-140', title:'Excel File Opens as Locked for Editing by Yourself', cat:'Microsoft 365', sub:'M365 Apps', tags:'excel,locked,editing,sharepoint,onedrive,business-user,office-excel', symptoms:'File says Locked for editing by [Your Own Name] and forces read-only mode.', cause:'Previous session was not properly closed — cloud server thinks your session is still active.', steps:['Fully close the local Excel application.','Open the file in Excel Online via browser (SharePoint or OneDrive).','The web interface forces the cloud server to clear the ghost lock.','Click Editing at the top and select Open in Desktop App.','Full read/write access is restored.'] },
  // ─── Daily Communication (USR-141 to USR-150) ───
  { code:'USR-141', title:'PDF Email Attachments Open in Browser Instead of Adobe', cat:'Software & Applications', sub:'Core Apps', tags:'pdf,adobe,browser,file-association,business-user', symptoms:'Double-clicking PDF attachments opens them in Edge or Chrome instead of Adobe Acrobat.', cause:'OS default file association was reset to web browsers during an app update.', steps:['Open File Explorer and locate any PDF file.','Right-click the PDF and select Open with > Choose another app.','Select Adobe Acrobat Reader or Adobe Acrobat Pro.','Check Always use this app to open .pdf files.','Click OK to permanently update the default.'] },
  { code:'USR-142', title:'Word Track Changes Mode Stuck On and Cannot Be Turned Off', cat:'Microsoft 365', sub:'M365 Apps', tags:'word,track-changes,review,document,business-user,office-word', symptoms:'All typed words appear as red underlined text with margin bars and Track Changes cannot be turned off.', cause:'Lock Tracking is enabled with a compliance password, or co-authoring loop is active.', steps:['Click the Review tab in the Word ribbon.','Click the dropdown arrow next to Track Changes and select Unlock Tracking (enter password if prompted).','In the Changes section, click the Accept dropdown.','Select Accept All Changes and Stop Tracking.','All edits merge into clean black text and tracking deactivates.'] },
  { code:'USR-143', title:'Teams Copilot Says I Need More Context or Fails to Summarize', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,teams,summary,chat-history,ms-copilot,business-user,office-teams', symptoms:'Copilot in Teams returns I need more context when asked to summarize a chat.', cause:'Chat history has not been loaded into the active view pane.', steps:['Close the Copilot panel.','Scroll up through the Teams chat thread to load older messages into view.','Scroll back down to the bottom.','Click the Copilot icon to reopen the panel.','Re-type your summary query — Copilot can now read the loaded history.'] },
  { code:'USR-144', title:'Shared Mailbox Folders Not Showing Recent Email Updates', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,shared-mailbox,sync,exchange,business-user,office-outlook', symptoms:'Shared mailbox shows outdated emails while colleagues see current messages.', cause:'Outlook is caching the shared mailbox locally and the update loop has hung.', steps:['Open Outlook > File > Account Settings > Account Settings.','Double-click your primary email account.','Click More Settings > Advanced tab.','Uncheck Download shared folders under Cached Exchange Mode Settings.','Click Apply, OK, and restart Outlook — shared folders now query Exchange in real time.'] },
  { code:'USR-145', title:'Out of Office Replies Still Sending After Being Turned Off', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,out-of-office,automatic-replies,email,business-user,office-outlook', symptoms:'Clients still receive out-of-office replies weeks after returning from vacation.', cause:'Mismatch between local client schedule and server-side mail handling rules.', steps:['Open outlook.office.com in a browser.','Click the gear icon > Mail > Automatic replies.','Toggle Automatic replies on to Off. Click Save.','If the issue returns, check Rules in both Outlook and the web app.','Delete any old rule titled Reply using a specific template.'] },
  { code:'USR-146', title:'SharePoint Site Shows Access Denied for a Site You Had Access to Yesterday', cat:'Account & Authentication', sub:'Shared Files', tags:'sharepoint,access-denied,permissions,browser,cookies,business-user', symptoms:'SharePoint site shows Access Denied or prompts to Request Access.', cause:'Browser is using an old expired login cookie from a past session.', steps:['Do not click Request Access.','Click the Padlock icon in the browser address bar.','Click Cookies and site data or Site settings.','Click Clear data and remove all sharepoint.com cookie entries.','Close and reopen the browser, navigate back to the site, and log in cleanly.'] },
  { code:'USR-147', title:'Office Apps Show Unlicensed Product Subscription Expired Banner', cat:'Account & Authentication', sub:'Identity & Access', tags:'office,license,unlicensed,subscription,microsoft-365,business-user', symptoms:'Yellow or red banner in Word, Excel, PowerPoint says Unlicensed Product — most features disabled.', cause:'Local identity licensing files entered a locked state causing a validation failure.', steps:['Close all Office apps. Open Settings > Accounts > Access work or school.','Find your corporate account, click it, and select Disconnect.','Open Credential Manager (search in Start Menu) > Windows Credentials.','Delete all entries prefixed with MicrosoftOffice16_Data: or IdentityCache.','Reboot, open Word, sign in with corporate credentials — license clears immediately.'] },
  { code:'USR-148', title:'Outlook Search Bar Moved to Top and Cannot Find Emails', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,search,email,find,business-user,office-outlook', symptoms:'Outlook updated and the search bar moved to the title bar — typing keywords yields poor results.', cause:'Microsoft redesigned the search UI to use centralized cloud query engines.', steps:['Click inside the top search bar to activate the Search ribbon.','In the Scope section of the ribbon, change from Current Mailbox to All Outlook Items.','Verify time filters are not restricting results to a narrow date range.','For best results, use specific keywords like sender name or subject line words.','If search is still incomplete, go to File > Options > Search and rebuild the search index.'] },
  { code:'USR-149', title:'Teams Status Shows Out of Office Even Though You Are at Your Desk', cat:'Microsoft 365', sub:'M365 Apps', tags:'teams,status,out-of-office,presence,calendar,business-user,office-teams', symptoms:'Teams shows Out of Office status with purple briefcase icon while actively working.', cause:'A past recurring calendar event did not clear properly when the schedule rolled over.', steps:['Open Outlook calendar and look for all-day blocks or vacation items scheduled for today.','Double-click any such event and check the Show As field.','Change it to Free or Tentative instead of Out of Office.','If an old vacation block is still running, right-click and Delete it.','Log out of Teams and log back in to push fresh presence signals.'] },
  { code:'USR-150', title:'Microsoft Forms Link Returns You Do Not Have Permission Error', cat:'Account & Authentication', sub:'Shared Files', tags:'forms,permissions,authentication,browser,business-user', symptoms:'Clicking a Forms survey link returns You do not have permission to view this form.', cause:'Browser is loading the page using personal Microsoft account cookies instead of corporate credentials.', steps:['Look at the top-right of the Forms page for any personal account avatar.','Click it and select Sign Out.','Close the browser window.','Open a new InPrivate or Incognito window.','Paste the form link and log in with your corporate credentials.'] },
  // ─── Teams & Collaboration (USR-151 to USR-158) ───
  { code:'USR-151', title:'Teams Status Stuck on Away While Actively Working', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,status,away,presence,activity,business-user,office-teams', symptoms:'Teams presence dot stays yellow Away even while typing and switching tabs.', cause:'A third-party app is locking system focus or Teams has been running in the background too long.', steps:['Click directly inside the Teams window to bring it to the front.','Click your profile picture > status dropdown > select Available.','Check if Focus Assist or Do Not Disturb is on in Windows taskbar settings — turn it off.','If status still does not update, right-click Teams in the system tray and select Quit.','Relaunch Teams from the Start Menu.'] },
  { code:'USR-152', title:'Outlook Emails Stuck in Outbox and Refusing to Send', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,outbox,email,stuck,send,business-user,office-outlook', symptoms:'Sent email sits in Outbox with italicized title and never reaches recipient.', cause:'Email was opened while in Outbox (stripping send instructions) or attachment is too large.', steps:['Click the Outbox folder in the Outlook sidebar.','Check attachment size — if over 25 MB, remove it and share via OneDrive link instead.','If no large attachment, close Outlook entirely.','Reopen Outlook and verify the status bar shows Connected to Microsoft Exchange.','Click the email in Outbox and click Send again without opening it.'] },
  { code:'USR-153', title:'Microphone Volume Too Low or Muffled in Video Meetings', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'microphone,audio,volume,teams,zoom,business-user,office-teams', symptoms:'Others say your voice sounds quiet or muffled during calls.', cause:'OS microphone input volume was automatically turned down by an audio optimization feature.', steps:['On Windows: open Start Menu > Sound Settings > Input section.','Click your active headset or microphone name.','Drag the Volume slider to 100%.','Click Test your microphone to verify the blue bar jumps cleanly.','On Mac: System Settings > Sound > Input tab > drag Input volume slider higher.'] },
  { code:'USR-154', title:'Teams or Zoom Meeting Link Loops and Will Not Launch Desktop App', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,zoom,meeting-link,popup,browser,business-user,office-teams', symptoms:'Clicking a meeting link opens a spinning browser tab but never launches the desktop app.', cause:'Browser has cached an old instruction to block external application popup calls.', steps:['Look in the browser URL bar for a blocked popup icon (red X on a window).','Click it and select Always allow popups and redirects from teams.microsoft.com.','If no icon, click Join on the web instead on the meeting page.','This launches the meeting in the browser tab so you do not miss the call.','To fix permanently, go to browser Settings > Privacy > Pop-ups and redirects > add teams.microsoft.com as allowed.'] },
  { code:'USR-155', title:'Accidentally Deleted a Critical OneDrive Folder', cat:'Cloud Services', sub:'Shared Files', tags:'onedrive,deleted,recycle-bin,restore,files,business-user', symptoms:'An entire OneDrive folder full of project files was accidentally deleted.', cause:'Folder was moved to the cloud Recycle Bin, which holds files for up to 93 days.', steps:['Open office.com in a browser and click OneDrive.','Click Recycle bin in the left navigation.','Find your deleted folder in the list.','Click the checkbox next to the folder name.','Click Restore — the folder and all files return to their original location.'] },
  { code:'USR-156', title:'Laptop Screen Brightness Slider Missing or Stuck', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'brightness,display,laptop,screen,driver,business-user', symptoms:'Brightness buttons on keyboard do nothing and the brightness slider is greyed out.', cause:'Graphics display system became confused after waking from an external monitor connection.', steps:['Press Win+X and select Device Manager.','Expand Display adapters.','Right-click your integrated graphics driver and select Disable device.','Wait 5 seconds, then right-click again and select Enable device.','Brightness sliders and keyboard buttons will work immediately after the graphics pipeline restarts.'] },
  { code:'USR-157', title:'Outlook Autocomplete Suggests Wrong or Old Email Address', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,autocomplete,email-address,cache,business-user,office-outlook', symptoms:'Outlook suggests an old or incorrect email address when typing a colleague name.', cause:'Outlook saved the old address in its local Autocomplete Cache.', steps:['Open a new email in Outlook and click in the To: field.','Type the first few letters of the person name until the wrong suggestion appears.','Look for the X icon on the far right of the dropdown suggestion.','Click the X to permanently delete that stale address from cache.','Type the correct email address manually — Outlook will save it for future suggestions.'] },
  { code:'USR-158', title:'Audio Echoing or Whistling Noise During a Video Call', cat:'Hardware & Peripherals', sub:'Audio & Video', tags:'echo,audio,feedback,video-call,teams,microphone,business-user,office-teams', symptoms:'Loud whistling or repeating echo fills the call when you unmute.', cause:'Laptop speakers are amplifying call audio that the microphone then picks up and re-amplifies.', steps:['Immediately click Mute to break the feedback loop.','Lower speaker volume below 50%.','Plug in headphones or earbuds to isolate audio to your ears.','If in a conference room, ensure only one device has mic and speakers active.','Enable noise suppression in Teams: Settings > Devices > Noise suppression > High.'] },
  // ─── Operating System & Layout (USR-159 to USR-166) ───
  { code:'USR-159', title:'Outlook Folder Sidebar Disappeared and Everything is Missing', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,folder-pane,sidebar,layout,business-user,office-outlook', symptoms:'Entire left-side folder list (Inbox, Sent Items) has vanished from Outlook.', cause:'Folder list layout was accidentally toggled to Hidden.', steps:['Click the View tab in the Outlook ribbon.','Locate the Layout section.','Click Folder Pane.','Select Normal from the dropdown.','The full folder sidebar will instantly slide back into view.'] },
  { code:'USR-160', title:'Blue Send Button Missing from Outlook Email Window', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,send-button,offline,exchange,business-user,office-outlook', symptoms:'The Send button is missing from a new email composition window.', cause:'Outlook switched to Offline mode.', steps:['Click the Send/Receive tab in the main Outlook ribbon.','Locate the Work Offline button on the far right.','If it is highlighted (dark grey or blue), click it once to turn it off.','The status bar at the bottom will change from Working Offline to Connected to Microsoft Exchange.','The Send button will reappear in all email composition windows.'] },
  { code:'USR-161', title:'File Saved in OneDrive Missing from Word Recent Files List', cat:'Microsoft 365', sub:'M365 Apps', tags:'word,recent-files,onedrive,history,business-user,office-word', symptoms:'A recently worked-on file does not appear in the Word Recent list.', cause:'App navigation history filled up or file was opened via an unmapped web link.', steps:['Open office.com in a browser and log in.','Click My Content in the left menu.','Click the Recent filter tab — the file will appear at the top.','Click the file to open it in the browser.','Click Open in Desktop App to pull it back into the local app history.'] },
  { code:'USR-162', title:'Mac Screenshot Shortcut Not Working or Files Missing', cat:'Software & Applications', sub:'macOS Endpoint', tags:'mac,screenshot,shortcut,macos,files,business-user', symptoms:'Cmd+Shift+4 does nothing or screenshots cannot be found after capture.', cause:'Default screenshot save destination was changed during a system patch.', steps:['Press Cmd+Shift+5 to open the screenshot utility panel.','Click Options in the panel.','Under Save to, ensure Desktop or Downloads is selected.','Press Escape to close the panel.','Try the screenshot shortcut again — files will appear in the designated location.'] },
  { code:'USR-163', title:'Mouse Scroll Wheel Scrolls in the Wrong Direction', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'mouse,scroll,direction,natural-scrolling,macos,windows,business-user', symptoms:'Rolling the scroll wheel down moves the page up instead of down.', cause:'OS defaults to Natural scrolling mode designed for touchscreens.', steps:['On Windows: open Start Menu > Mouse settings. Find Scrolling direction and switch to Standard.','On Mac: click Apple menu > System Settings > Mouse.','Locate the Natural scrolling toggle.','Toggle it to Off.','Mouse wheel now follows traditional scrolling — down moves the page down.'] },
  { code:'USR-164', title:'Windows Snipping Tool Displays Screen Snipping Capability Broken Error', cat:'Software & Applications', sub:'Windows Endpoint', tags:'snipping-tool,screenshot,windows,broken,business-user', symptoms:'Snipping Tool freezes and shows capabilities are broken error when trying to capture.', cause:'App graphics cache entered an unhandled exception state after a sleep cycle.', steps:['Open Start Menu > Apps > Installed apps.','Find Snipping Tool in the list.','Click ... > Advanced options.','Click Repair first — this fixes file links without losing settings.','If still broken, click Reset to restore the app to factory state.'] },
  { code:'USR-165', title:'Too Many Notifications Popping Up While Presenting or Focusing', cat:'Software & Applications', sub:'Windows Endpoint', tags:'notifications,focus,do-not-disturb,windows,business-user', symptoms:'Email alerts, chat toasts, and system popups fly onto screen while presenting.', cause:'Focus notification settings are set to allow all background app overrides.', steps:['Click the clock area in the bottom-right taskbar.','Click Focus or the gear icon to open Focus settings.','Toggle Do Not Disturb to On to mute all toast popups.','Go to Settings > System > Notifications > Turn on Do Not Disturb automatically.','Check When duplicating my display and When playing a full-screen application.'] },
  { code:'USR-166', title:'Teams Chat Text Size Too Small or Too Large After Accidental Zoom', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,zoom,text-size,font,display,business-user,office-teams', symptoms:'Teams chat text is microscopic or giant after accidentally hitting a keyboard zoom shortcut.', cause:'Ctrl+scroll wheel accidentally triggered zoom inside the Teams window.', steps:['Click inside the Teams chat pane to set focus there.','Press Ctrl+0 on Windows (or Cmd+0 on Mac) to reset zoom to 100%.','Text will immediately return to the standard default size.','To adjust permanently: use Ctrl+Plus to zoom in or Ctrl+Minus to zoom out.','Teams also has a built-in text size setting under Settings > Appearance.'] },
  // ─── Daily Work Station Hardware (USR-167 to USR-175) ───
  { code:'USR-167', title:'Keyboard NumPad Types Arrows Instead of Numbers', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'keyboard,numpad,num-lock,arrows,hardware,business-user', symptoms:'Numeric keypad types arrow navigation commands instead of numbers.', cause:'Num Lock was accidentally deactivated.', steps:['Locate the Num Lock (or NumLk) key in the upper-left of the numeric keypad.','Press the Num Lock key once.','Look for the LED indicator light to illuminate on the keyboard.','Try typing in Excel — keys will now output numbers correctly.','If no Num Lock key, press Fn+F11 on some laptop keyboards.'] },
  { code:'USR-168', title:'Desk Phone Screen Shows No Network or Disconnected Error', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'desk-phone,network,ethernet,hardware,business-user', symptoms:'Physical desk phone shows No Network connection or IP Address Assignment Failure.', cause:'Ethernet cable dropped its connection or docking station broke network routing.', steps:['Locate the network cable plugged into the LAN port on the back of the phone.','Pull the cable out and plug it back in firmly until you hear a click.','Follow the cable to the wall outlet or dock and reseat it there too.','If still dead, pull the power adapter out of the phone base.','Wait 10 seconds and plug it back in to force a firmware reboot.'] },
  { code:'USR-169', title:'Mac Battery Draining Extremely Fast After an App Update', cat:'Software & Applications', sub:'macOS Endpoint', tags:'mac,battery,drain,cpu,performance,macos,business-user', symptoms:'MacBook battery drops rapidly and the base feels hot after an app update.', cause:'A background app thread is stuck in an unhandled exception loop running CPU at 100%.', steps:['Press Cmd+Spacebar and type Activity Monitor, then press Enter.','Click the CPU tab.','Click the % CPU column header to sort by highest usage.','Identify any app running at 95%+ CPU while you are not using it.','Click the X button in the top-left of Activity Monitor and click Force Quit.'] },
  { code:'USR-170', title:'Cannot Drag and Drop Files Into Browser or Teams Chat', cat:'Software & Applications', sub:'Web Browsers', tags:'drag-drop,browser,teams,upload,permissions,business-user,office-teams', symptoms:'Mouse cursor shows a restricted circle symbol when dragging files to upload.', cause:'Security permission mismatch — one app runs as Administrator while the other runs as standard user.', steps:['Close both the source app (File Explorer) and the target app (browser or Teams).','Do not use Run as Administrator shortcuts for work applications.','Relaunch both apps normally from the Start Menu.','Try dragging the file again — the restriction symbol will be gone.','If issue persists, right-click File Explorer shortcut > Properties and ensure Run as administrator is unchecked.'] },
  { code:'USR-171', title:'Multi-Monitor Mouse Alignment is Vertically Inverted', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,multi-monitor,display-settings,alignment,hardware,business-user', symptoms:'Mouse has to go off the bottom edge to reach the monitor mounted above the laptop.', cause:'OS maps secondary screens side-by-side by default instead of stacked vertically.', steps:['Right-click the desktop and select Display settings.','Look at the blue numbered display rectangles at the top.','Click and hold Monitor 2 and drag it vertically above Monitor 1 to match your physical layout.','Click Apply.','Mouse cursor will now cross naturally between displays matching your physical setup.'] },
  { code:'USR-172', title:'Teams Call Shows Call on Hold Banner When Switching Devices', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,call-on-hold,device-switch,mobile,business-user,office-teams', symptoms:'Laptop Teams screen shows permanent Call on Hold banner after switching from phone.', cause:'Phone session handles did not clear fast enough, blocking laptop from taking over the stream.', steps:['On your phone, open Teams and click the red Hang Up button to disconnect that device.','On your laptop Teams screen, click the red Leave button.','Wait 5 seconds for cloud session handles to clear.','Open Teams calendar, double-click the meeting, and click a fresh Join button.','Select your intended device preferences to connect normally.'] },
  { code:'USR-173', title:'Outlook Signature Panel Crashes When Clicked', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,signature,crash,office,registry,business-user,office-outlook', symptoms:'Clicking Signatures in Outlook settings causes the app to freeze and crash.', cause:'Registry conflict between pre-installed OEM Office Desktop Apps and corporate Microsoft 365.', steps:['Open Start Menu > Installed apps (or Programs and Features).','Search for Microsoft Office Desktop Apps.','If found, click ... > Uninstall and confirm removal.','This does not affect your enterprise Microsoft 365 Apps for Enterprise installation.','Restart your computer — Outlook Signatures will load instantly without crashing.'] },
  { code:'USR-174', title:'Laptop Trackpad Clicks Randomly While Typing', cat:'Hardware & Peripherals', sub:'Peripherals', tags:'trackpad,touchpad,palm-rejection,typing,hardware,business-user', symptoms:'Cursor jumps to random locations mid-sentence while typing.', cause:'Palm or wrist is lightly brushing the trackpad while typing.', steps:['Open Start Menu > Touchpad settings.','Expand the Taps section.','Find the Touchpad sensitivity dropdown.','Change it from Medium or High to Low Sensitivity.','This tells the OS to ignore brief soft palm contact while typing.'] },
  { code:'USR-175', title:'Laptop Fan Making Loud Clicking or Whirring Noise', cat:'Hardware & Peripherals', sub:'Daily Work Station', tags:'fan,noise,laptop,cooling,hardware,business-user', symptoms:'Laptop fan spins loudly like a jet engine and the base feels hot.', cause:'Cooling vents are blocked by dust or a background tab is consuming excessive memory.', steps:['Save files and close browser tabs you do not need.','Pick up the laptop and inspect the bottom and side ventilation grilles.','Use a microfiber cloth or compressed air to clear dust from the vents.','Always use the laptop on a hard flat surface — never on blankets or carpets.','If fan noise persists after cleaning, contact IT for hardware inspection.'] },
  // ─── Smart Printing & Hardware (USR-176 to USR-180) ───
  { code:'USR-176', title:'Office Printer Shows Offline on Your Machine but Works for Everyone Else', cat:'Hardware & Peripherals', sub:'Printing', tags:'printer,offline,print-queue,network,business-user', symptoms:'Printer status shows Offline on your laptop while colleagues print successfully.', cause:'Local print manager cached an old network routing path that failed during a network glitch.', steps:['Open Start Menu > Printers & scanners.','Click the printer name > Open print queue.','In the queue window, click the Printer menu tab.','If Use Printer Offline has a checkmark, click it to uncheck it.','Status returns to Online immediately.'] },
  { code:'USR-177', title:'Secure Print Badge Reader Shows No Jobs Found', cat:'Hardware & Peripherals', sub:'Printing', tags:'printer,secure-print,badge,follow-me-print,business-user', symptoms:'Scanning badge at office printer shows No active print jobs found for this account.', cause:'Printer properties have an outdated username that does not match your current cloud identity.', steps:['Go to Control Panel > Devices and Printers.','Right-click your secure print queue (e.g., Follow-Me-Print) > Printing Preferences.','Click the Job Storage or Secure Print tab.','Change User ID from Automatic to Custom and type your corporate network username.','Click Apply, OK, and resubmit your print job.'] },
  { code:'USR-178', title:'PDF Documents Printing as Gibberish Symbols and Code', cat:'Hardware & Peripherals', sub:'Printing', tags:'pdf,printing,gibberish,adobe,fonts,business-user', symptoms:'Printer outputs pages of random symbols and code instead of document text.', cause:'PDF contains complex embedded fonts the printer hardware cannot decode natively.', steps:['Open the PDF in Adobe Acrobat Reader.','Click File > Print.','In the print dialog, click Advanced next to the printer name.','Check the Print as Image checkbox.','Click OK then Print — Adobe converts text to image before sending to the printer.'] },
  { code:'USR-179', title:'Printer Pauses with Red Light Flashing for Paper Size Mismatch', cat:'Hardware & Peripherals', sub:'Printing', tags:'printer,paper-size,a4,letter,mismatch,business-user', symptoms:'Printer stops and flashes red, showing Load A4 Paper in Tray 2 error.', cause:'Document was created with A4 dimensions but printer trays contain US Letter paper.', steps:['Do not touch the printer trays. Return to your workstation.','Open the print queue and cancel the stuck document.','Open the document in Word or Adobe.','Go to File > Print Layout / Page Setup.','Change paper size from A4 to Letter (or select Fit to Printable Area) and resubmit.'] },
  { code:'USR-180', title:'Outlook Search Not Finding Recent Emails from This Morning', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,search,recent-emails,inbox,business-user,office-outlook', symptoms:'Outlook search finds old emails but misses a message received this morning.', cause:'Search scope is restricted to a narrow folder or time filter is excluding recent items.', steps:['Click in the Outlook search box to activate the Search ribbon.','In the Scope section, change from Current Folder to All Outlook Items.','Ensure the folder filter below the search box is set to All rather than Unread.','In the Refine ribbon, ensure All Dates is selected rather than This Week.','If results are still delayed, clear the search and try again with a different keyword.'] },
  // ─── Secure Access & Identity (USR-181 to USR-186) ───
  { code:'USR-181', title:'Accidentally Sent an Email to the Wrong Person — How to Recall It', cat:'Account & Authentication', sub:'Outlook Email', tags:'outlook,recall,email,sent,business-user,office-outlook', symptoms:'Email with confidential data was sent to the wrong address.', cause:'Standard email routing is instant but internal corporate accounts support recall if unopened.', steps:['Go to your Sent Items folder in Outlook.','Double-click the email to open it in its own window.','Click File > Info.','Click Message Resend and Recall.','Select Recall This Message > Delete unread copies, check the confirmation box, and click OK.'] },
  { code:'USR-182', title:'Login Screen Shows You Can\'t Get There from Here Access Block', cat:'Account & Authentication', sub:'Identity & Access', tags:'conditional-access,vpn,compliant-device,entra-id,business-user', symptoms:'Corporate apps show You can\'t get there from here. This application requires a compliant device.', cause:'Conditional Access policies block access unless using a secure VPN or registered company device.', steps:['Locate your VPN client in the taskbar notification tray.','Open the VPN and click Connect. Complete MFA.','Return to the browser and press Ctrl+Shift+R for a hard refresh.','The corporate login server will now recognize your compliant device and grant access.','If still blocked, contact IT — your device may need to be enrolled in Intune.'] },
  { code:'USR-183', title:'Corporate Account Keeps Locking Out Right After Password Change', cat:'Account & Authentication', sub:'Identity & Access', tags:'account-lockout,password,smartphone,wifi,entra-id,business-user', symptoms:'Account locks out repeatedly minutes after changing password.', cause:'Personal smartphone connected to corporate Wi-Fi is firing the old expired password in the background.', steps:['Pick up your personal smartphone.','Open phone Settings > Wi-Fi.','Tap the corporate network SSID and select Forget This Network.','This stops the phone from firing stale authentication requests.','Wait 10 minutes, clear saved browser passwords on your computer, and log in cleanly.'] },
  { code:'USR-184', title:'SharePoint Team Document Shows Access Denied or Request Access Screen', cat:'Account & Authentication', sub:'Shared Files', tags:'sharepoint,access-denied,cookies,browser,business-user', symptoms:'SharePoint document link shows Access Denied instead of the file library.', cause:'Browser is using an expired authentication cookie from an old session.', steps:['Do not click Request Access.','Click the Padlock icon in the browser address bar.','Click Cookies and site data.','Click Clear data and remove all sharepoint.com entries.','Close and reopen the browser, paste the link, and log in cleanly.'] },
  { code:'USR-185', title:'OneDrive File Shows Blue Cloud Icon with Red Error X Badge', cat:'Cloud Services', sub:'Shared Files', tags:'onedrive,sync-error,red-x,filename,sharepoint,business-user', symptoms:'A single OneDrive file has a red X circle while all others show green checkmarks.', cause:'Filename contains illegal characters or the folder path exceeds character limits.', steps:['Hover over the OneDrive tray icon to see the error details.','Note the filename flagged in the error.','Right-click the file > Rename and remove any symbols or trailing spaces.','Keep the filename short and simple.','If buried deep in subfolders, drag the file to a parent folder to reduce path depth.'] },
  { code:'USR-186', title:'Cannot See the Chat Panel During a Large Teams Meeting', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,chat,town-hall,meeting,permissions,business-user,office-teams', symptoms:'Chat icon is missing or greyed out during a large Teams town hall or training call.', cause:'Meeting organizer disabled public chat to minimize distractions during presentations.', steps:['This is not a bug — chat is controlled by the meeting host.','Look for a Q&A button in the top meeting menu bar.','Click Q&A to open the moderated side panel.','Type your question in the Q&A text field and click Submit.','Your question is queued for the presenters to address.'] },
  // ─── Web Browser Optimization (USR-187 to USR-192) ───
  { code:'USR-187', title:'Chrome or Edge Shows Aw Snap Error on Corporate Web Apps', cat:'Software & Applications', sub:'Web Browsers', tags:'browser,chrome,edge,crash,aw-snap,web-app,business-user', symptoms:'Browser tab crashes with Aw, Snap! error while using corporate web tools.', cause:'Web app encountered a memory leak consuming all available browser sandbox memory.', steps:['Press Ctrl+Shift+R to hard refresh the page.','Click the extension icon and disable third-party extensions.','Go to browser Settings > System > enable Memory Saver or Efficiency Mode.','Clear cache: Ctrl+Shift+Delete > Cached images and files > Clear data.','Try opening the app in InPrivate/Incognito mode to test without extensions.'] },
  { code:'USR-188', title:'Accidentally Closed Browser Window with 20 Important Tabs', cat:'Software & Applications', sub:'Web Browsers', tags:'browser,tabs,restore,session,chrome,edge,business-user', symptoms:'Entire browser window with dozens of critical tabs was accidentally closed.', cause:'Browser preserves session navigation logs in an emergency recovery buffer.', steps:['Relaunch the browser from the desktop or taskbar.','Press Ctrl+Shift+T on Windows (or Cmd+Shift+T on Mac).','The browser will restore the entire closed window including all tabs.','All text entries in forms will also be restored from the session buffer.','Repeat Ctrl+Shift+T to restore additional previously closed windows.'] },
  { code:'USR-189', title:'Laptop Shows Plugged In Not Charging When Connected to Dock', cat:'Hardware & Peripherals', sub:'Daily Work Station', tags:'laptop,charging,docking-station,battery,power-delivery,business-user', symptoms:'Battery level drops slowly even though laptop is connected to the docking station.', cause:'Dock power adapter is on a low-wattage strip or power delivery negotiation failed.', steps:['Disconnect the USB-C dock cable from your laptop.','Unplug the power cord from the docking station. Wait 15 seconds.','Ensure the dock power cord plugs directly into a wall outlet, not a daisy-chained power strip.','Plug the power cord back into the dock.','Reconnect the USB-C cable to your laptop to re-baseline power delivery.'] },
  { code:'USR-190', title:'External Monitor Shows Pink Blue or Green Color Tint Overlay', cat:'Hardware & Peripherals', sub:'Monitors & Displays', tags:'monitor,color-tint,hdmi,displayport,cable,hardware,business-user', symptoms:'Secondary monitor displays a strange color tint overlay over everything.', cause:'Video cable pins have backed out slightly, dropping specific color data streams.', steps:['Locate the HDMI or DisplayPort cable running to the monitor.','Pull the cable out of the monitor port completely.','Wait 5 seconds and push it back in firmly until it bottoms out.','Follow the cable to the laptop or dock and reseat it there too.','Inspect the metal pins for dust and clean if needed.'] },
  { code:'USR-191', title:'Copilot Returns This Content Is Blocked by Organizational Policy', cat:'Microsoft 365', sub:'Microsoft Copilot', tags:'copilot,dlp,policy,blocked,compliance,ms-copilot,business-user', symptoms:'Copilot stops mid-response and shows This content is blocked by corporate compliance DLP policies.', cause:'Prompt contained sensitive data strings (credit card formats, SSNs, passwords) that triggered DLP guardrails.', steps:['This is an intentional security block to protect company data.','Review the text you tried to feed into Copilot.','Remove any sensitive personal identifiers, account strings, or password keys.','Replace sensitive data with generic placeholders like [Customer_A_Data] or [Revenue_Value_X].','Resubmit the cleaned prompt — Copilot will process the structural logic safely.'] },
  { code:'USR-192', title:'Outlook Status Bar Shows Disconnected Warning', cat:'Microsoft 365', sub:'M365 Apps', tags:'outlook,disconnected,exchange,sync,business-user,office-outlook', symptoms:'Outlook inbox has not received new mail for hours and shows Disconnected in the status bar.', cause:'App connection loops dropped sync links after laptop roamed between Wi-Fi networks.', steps:['Click the Send/Receive tab in the Outlook ribbon.','Locate the Work Offline button on the far right.','Click Work Offline once to turn it On (status bar shows Working Offline).','Wait 10 seconds.','Click Work Offline again to toggle it Off — Outlook re-establishes a clean sync bridge to Exchange.'] },
  // ─── Remote Work & Mobility (USR-193 to USR-200) ───
  { code:'USR-193', title:'OneDrive Folder Items Show a Grey Padlock Icon Overlay', cat:'Cloud Services', sub:'Shared Files', tags:'onedrive,padlock,read-only,permissions,sharepoint,business-user', symptoms:'Files in OneDrive show a grey padlock badge next to the green sync checkmark.', cause:'File has encryption rules or is marked Read-Only from a restricted SharePoint library.', steps:['Right-click the file with the padlock icon and select Properties.','Click the General tab.','Look for the Read-only checkbox under Attributes.','If checked, uncheck it and click Apply.','If padlock remains, the SharePoint library has locked edit permissions — use File > Save As to save a personal copy.'] },
  { code:'USR-194', title:'PowerPoint Slides Lag and Stutter During Projector Presentation', cat:'Microsoft 365', sub:'M365 Apps', tags:'powerpoint,presentation,projector,lag,performance,business-user,office-powerpoint', symptoms:'Slide transitions freeze or lag several seconds when presenting on a projector.', cause:'PowerPoint uses high-resolution rendering across both screens, overloading integrated graphics.', steps:['Open PowerPoint and click the Slide Show tab.','Locate the Monitors section on the far right of the ribbon.','Find the Resolution dropdown.','Change it from Fastest/Current Resolution to 1280x720 or 1920x1080.','This reduces graphics load by over 50%, ensuring smooth slide transitions.'] },
  { code:'USR-195', title:'Teams Video Background Blur Keeps Flickering During Calls', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,background-blur,virtual-background,video,camera,business-user,office-teams', symptoms:'Virtual background or blur flickers and shows the real room background during calls.', cause:'Room lighting is too dim or shirt color matches the wall, confusing the AI edge detection.', steps:['Turn on a desk lamp positioned in front of your face.','Avoid sitting with bright windows directly behind you.','In the Teams meeting, click More > Device settings > Video effects.','Switch from custom virtual background images to the basic Blur option.','Basic blur is more stable and resistant to edge tracking dropouts in poor lighting.'] },
  { code:'USR-196', title:'Forgot Corporate Network Password While Working Remotely', cat:'Account & Authentication', sub:'Identity & Access', tags:'password-reset,remote-work,sspr,entra-id,business-user', symptoms:'Completely forgot corporate password and locked out of laptop while working from home.', cause:'Security tokens expired but self-service password reset is available via phone verification.', steps:['Do not guess the password more than 3 times to avoid global lockout.','On your personal phone, open a browser and go to passwordreset.microsoftonline.com.','Enter your corporate email address and solve the captcha.','Choose to receive a text code or verification call to your registered phone.','Enter the code, set a new password, and log in after 2 minutes of sync time.'] },
  { code:'USR-197', title:'VPN Disconnects Every Time Laptop Goes to Sleep', cat:'Network & Connectivity', sub:'Wireless & Internet', tags:'vpn,sleep,power-management,network-adapter,remote-work,business-user', symptoms:'VPN requires full re-authentication every time the laptop wakes from sleep.', cause:'OS power settings shut down the network adapter during sleep, tearing down the VPN tunnel.', steps:['Open Start Menu > Power & battery.','Expand Screen and sleep settings.','Change When plugged in, put my device to sleep after to 30 Minutes or Never.','This keeps network adapters powered during brief desk breaks.','For the VPN adapter specifically: Device Manager > Network adapters > VPN adapter > Power Management > uncheck Allow the computer to turn off this device to save power.'] },
  { code:'USR-198', title:'Cannot Find a File a Teammate Just Uploaded to Teams Channel', cat:'Microsoft 365', sub:'M365 Apps', tags:'teams,files,sharepoint,channel,refresh,business-user,office-teams', symptoms:'A file a colleague just uploaded to a Teams channel is not visible in the Files tab.', cause:'Teams uses a cached database that delays checking cloud document libraries.', steps:['Navigate to the Teams channel where the file was shared.','Click the Files tab at the top.','Click the Refresh button in the ribbon below the tabs.','Teams drops its cache and queries SharePoint directly — the file will appear.','Alternatively, click Open in SharePoint to view the folder in a browser immediately.'] },
  { code:'USR-199', title:'Microsoft Forms Shows Maximum Character Limit Exceeded Error', cat:'Microsoft 365', sub:'M365 Apps', tags:'forms,character-limit,survey,microsoft-365,business-user', symptoms:'Submitting a Forms survey fails with Maximum character limit exceeded error.', cause:'Form creator set a strict character limit (typically 4000 chars) on the text field.', steps:['Do not refresh or close the browser tab — this will erase your response.','Press Ctrl+A then Ctrl+C to copy your entire response text.','Open Notepad or Word and paste the text to save a backup.','Edit and shorten your response to fit within the character limit.','Paste the condensed text back into the form field and submit.'] },
  { code:'USR-200', title:'Microsoft Teams App Showing a Very Old Version After Update Attempt', cat:'Microsoft 365', sub:'Microsoft Teams', tags:'teams,update,version,outdated,business-user,office-teams', symptoms:'Teams shows an outdated version number even after clicking Check for updates.', cause:'Teams update service is blocked by a corporate policy or the update cache is corrupted.', steps:['Click your profile picture in Teams > Check for updates.','If no update installs, close Teams completely (right-click system tray > Quit).','Open File Explorer and navigate to %localappdata%\\Microsoft\\Teams.','Delete the folder named Update.exe.staging if present.','Reopen Teams from the Start Menu — it will download and install the latest version automatically.'] },
];

console.log(`Preparing to insert ${articles.length} KB articles...`);

let inserted = 0;
let skipped = 0;

for (const art of articles) {
  const content = buildContent(art.code, art.title, art.cat, art.symptoms, art.cause, art.steps);
  
  // Check if article already exists by articleCode or title
  const [existing] = await conn.execute(
    'SELECT id FROM kbArticles WHERE articleCode = ? OR title = ? LIMIT 1',
    [art.code, art.title]
  );
  
  if (existing.length > 0) {
    // Update existing article
    await conn.execute(
      `UPDATE kbArticles SET 
        title = ?, content = ?, category = ?, subcategory = ?, audience = ?, 
        difficulty = ?, estimatedResolutionTime = ?, tags = ?, isPublished = 1, 
        ariaEnabled = ?, articleCode = ?, syncSource = 'user-kb-v1', updatedAt = ?
       WHERE articleCode = ? OR title = ?`,
      [art.title, content, art.cat, art.sub, 'end-user', 'beginner', 
       art.estimatedResolutionTime || '5-10 min', art.tags, 1, art.code, now, art.code, art.title]
    );
    skipped++;
  } else {
    // Insert new article
    await conn.execute(
      `INSERT INTO kbArticles 
        (title, content, category, subcategory, audience, difficulty, estimatedResolutionTime, 
         tags, isPublished, ariaEnabled, articleCode, syncSource, createdAt, updatedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, 'user-kb-v1', ?, ?)`,
      [art.title, content, art.cat, art.sub, 'end-user', 'beginner',
       art.estimatedResolutionTime || '5-10 min', art.tags, 1, art.code, now, now]
    );
    inserted++;
  }
}

console.log(`✅ Done! Inserted: ${inserted}, Updated: ${skipped}, Total: ${articles.length}`);

// Verify final count
const [countResult] = await conn.execute('SELECT COUNT(*) as total FROM kbArticles WHERE isPublished = 1');
console.log(`Total published KB articles in database: ${countResult[0].total}`);
await conn.end();
